<article class="ca-card ca-register-card" data-auth-card>
<header class="ca-card-head"><span class="ca-card-icon"><i class="fa-solid fa-user-plus"></i></span><div><p class="ca-overline">Join the community</p><h2>Create your account</h2></div></header>
<p class="ca-card-copy">A few details are all you need. Delivery addresses can be added securely during checkout.</p>
<form id="customer-auth-form" class="ca-auth-form" novalidate data-auth-form="register" data-api-endpoint="/api/v1/customer/auth/register">
<div class="ca-form-alert" role="alert" aria-live="assertive" tabindex="-1" hidden data-form-alert></div><div class="cc-form-grid ca-form-grid">
<div class="cc-field ca-field"><label for="register-first">First name</label><div class="ca-input-wrap"><i class="fa-regular fa-user"></i><input class="cc-input" id="register-first" name="first_name" required minlength="2" maxlength="60" autocomplete="given-name" placeholder="First name" aria-describedby="register-first-error"></div><small class="ca-field-error" id="register-first-error" data-error-for="first_name"></small></div>
<div class="cc-field ca-field"><label for="register-last">Last name</label><div class="ca-input-wrap"><i class="fa-regular fa-user"></i><input class="cc-input" id="register-last" name="last_name" required minlength="2" maxlength="60" autocomplete="family-name" placeholder="Last name" aria-describedby="register-last-error"></div><small class="ca-field-error" id="register-last-error" data-error-for="last_name"></small></div>
<div class="cc-field ca-field full"><label for="register-email">Email address</label><div class="ca-input-wrap"><i class="fa-regular fa-envelope"></i><input class="cc-input" id="register-email" name="email" type="email" required maxlength="254" autocomplete="email" inputmode="email" placeholder="you@example.com" aria-describedby="register-email-error"></div><small class="ca-field-error" id="register-email-error" data-error-for="email"></small></div>
<div class="cc-field ca-field full"><label for="register-phone">Indian mobile number</label><div class="ca-input-wrap ca-phone-wrap"><span>+91</span><input class="cc-input" id="register-phone" name="phone" type="tel" required maxlength="10" inputmode="numeric" autocomplete="tel-national" placeholder="98765 43210" aria-describedby="register-phone-error" data-indian-phone></div><small class="ca-field-error" id="register-phone-error" data-error-for="phone"></small></div>
<div class="cc-field ca-field full"><label for="register-password">Create password</label><div class="ca-input-wrap"><i class="fa-solid fa-key"></i><input class="cc-input" id="register-password" name="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password" placeholder="Create a strong password" aria-describedby="password-rules register-password-error"><button class="ca-password-toggle" type="button" data-password-toggle="register-password" aria-label="Show password"><i class="fa-regular fa-eye"></i></button></div><small class="ca-field-error" id="register-password-error" data-error-for="password"></small></div>
<div class="cc-field ca-field full"><label for="register-confirm">Confirm password</label><div class="ca-input-wrap"><i class="fa-solid fa-lock"></i><input class="cc-input" id="register-confirm" name="confirm_password" type="password" required minlength="12" maxlength="128" autocomplete="new-password" placeholder="Enter the same password again" aria-describedby="register-confirm-error"><button class="ca-password-toggle" type="button" data-password-toggle="register-confirm" aria-label="Show password"><i class="fa-regular fa-eye"></i></button></div><small class="ca-field-error" id="register-confirm-error" data-error-for="confirm_password"></small></div>
</div>
<div class="ca-password-meter" id="password-rules" data-password-meter data-score="0"><span><b></b></span><p>Password strength: <strong>Not entered</strong></p></div><ul class="ca-password-rules"><li data-rule="length"><i class="fa-solid fa-circle"></i> 12+ characters</li><li data-rule="case"><i class="fa-solid fa-circle"></i> Upper and lowercase</li><li data-rule="number"><i class="fa-solid fa-circle"></i> One number</li><li data-rule="symbol"><i class="fa-solid fa-circle"></i> One symbol</li></ul>
<label class="cc-check ca-consent"><input name="terms" type="checkbox" value="1" required><span>I agree to the <a href="../../../../terms.html">Terms of Use</a> and acknowledge the <a href="../../../../privacy.html">Privacy Notice</a>.</span></label><label class="cc-check ca-consent"><input name="marketing" type="checkbox" value="1"><span>Send me optional artisan stories, event news and thoughtful offers.</span></label>
<button class="cc-btn primary ca-submit" type="submit" data-submit-button><span>Create my account</span><i class="fa-solid fa-arrow-right"></i><i class="fa-solid fa-circle-notch fa-spin ca-spinner" aria-hidden="true"></i></button></form>
<section class="ca-success-panel" hidden data-register-success tabindex="-1"><span><i class="fa-solid fa-check"></i></span><h3>Your demo account is ready</h3><p>No password was stored. The screen is ready to receive the real registration API response.</p><a class="cc-btn primary" href="../index.php?demo=1">Open customer dashboard</a></section>
<p class="ca-switch">Already have an account? <a href="login.php">Sign in instead</a></p>
</article>
